/// @brief 只封装世界出生参数；生命/分数为原始点数，随机横坐标仅在出生时按固定种子求值。
/// 素材槽借用Extra清单；高度保持源平面的0，后续三维运动由各演员独占的LiftedPath推进。
SpawnActors Spawn(Vector3 position,const behavior::Pattern& pattern,float health,int score,int item,bool mirrored,bool randomX,unsigned seed,VisualId visual) {
    return {behavior::Spawn{.position=position,.pattern=pattern,.mirrored=mirrored,.randomX=randomX,.sourceHealth=health,
        .sourceScore=score,.seed=seed,.sourceItem=item,.visual=visual,.hitRadius=0.625F,.bulletBase=kNativeBulletBase,
        .laserBase=kNativeLaserBase,.defeatBase=kNativeDefeat,.fallback=kBlueBullet,.retirementHeights=Vector2{-10.5F,10.5F}},1,0};
}
